import React, {
    createContext,
    useContext,
    ReactNode,
    useState,
} from 'react';

type listDataType = {
    firstCard: number;
    id: string;
};

type StateContext = {
    listData: listDataType[];
    setlistData: (value: listDataType[]) => void;

    loading: boolean;
    setLoading: (value: boolean) => void;

    total: number;
    setTotal: (value: number) => void;

    perPage: number;
    setPerPage: (value: number) => void;

    getList: {};
    setGetList: (value: {}) => void;

    isMountedApi: boolean;
    setIsMountedApi: (value: boolean) => void;

    keyboardActive: boolean;
    setKeyboardActive: (value: boolean) => void;

    shoppingCartItem: number[] | [];
    setShoppingCartItem: (value: number[] | []) => void;

    selectedNumber: number | null
    setSelectedNumber: (value: number | null) => void

    shoppingCartActive: boolean
    setShoppingCartActive: (value: boolean) => void
};

type ProviderProps = {
    children: ReactNode;
};

export const Context = createContext({} as StateContext);

const Provider = ({ children }: ProviderProps) => {
    const [listData, setlistData] = useState<listDataType[]>([]);
    const [loading, setLoading] = useState(false);
    const [total, setTotal] = useState(101);
    const [perPage, setPerPage] = useState(84);
    const [getList, setGetList] = useState({});
    const [isMountedApi, setIsMountedApi] = useState(false);
    const [keyboardActive, setKeyboardActive] = useState(false);
    const [shoppingCartItem, setShoppingCartItem] = useState([]);
    const [shoppingCartActive, setShoppingCartActive] = useState(false);
    const [selectedNumber, setSelectedNumber] = useState(null);

    return (
        <Context.Provider value={{
            listData,
            setlistData,

            loading,
            setLoading,

            total,
            setTotal,

            perPage,
            setPerPage,

            getList,
            setGetList,

            isMountedApi,
            setIsMountedApi,

            keyboardActive,
            setKeyboardActive,

            shoppingCartActive,
            setShoppingCartActive,

            shoppingCartItem,
            setShoppingCartItem,

            selectedNumber,
            setSelectedNumber,


        } as StateContext}>
            {children}
        </Context.Provider>
    );
};

function useContexState() {
    const context = useContext(Context);
    return context;
};

export {
    Provider,
    useContexState
};
